def classify_network(distance_meters):
    if distance_meters <= 10:
        return "WPAN (Bluetooth/Zigbee)"
    elif distance_meters <= 100:
        return "WLAN (Wi-Fi)"
    elif distance_meters <= 50000:
        return "WMAN (WiMAX)"
    else:
        return "WWAN / Cellular / Satellite"
print(classify_network(50))

def validate_2ghz_channels(ap_list):
    allowed = {1, 6, 11}
    for ap_id, ch in ap_list:
        if ch not in allowed:
            print(f"AP {ap_id} uses invalid channel {ch}. Use 1, 6, or 11.")
        else:
            print(f"AP {ap_id} channel {ch} is valid.")

ap_deployments = [('AP1', 1), ('AP2', 3), ('AP3', 11)]
validate_2ghz_channels(ap_deployments)

def select_pan_tech(range_m, data_rate_kbps, needs_positioning):
    if range_m < 0.1:
        return "NFC"
    elif needs_positioning and range_m < 50:
        return "UWB"
    elif data_rate_kbps <= 250 and range_m < 100:
        return "Zigbee"
    return "Bluetooth / Wi-Fi"

