def process_call_event(current_state, event):
    transitions = {
        ("IDLE", "DIAL"): "AUTHENTICATING",
        ("AUTHENTICATING", "AUTH_SUCCESS"): "CALL_INITIATED",
        (
            "CALL_INITIATED",
            "TCH_ASSIGNED",
        ): "CONNECTING",
        ("CONNECTING", "CALLEE_ANSWER"): "ACTIVE",
    }
    return transitions.get((current_state, event), current_state)

print(process_call_event("IDLE", "DIAL"))  # Output: AUTHENTICATING

