def mobility_cost(update_rate, update_cost, call_rate, page_cost):
    return (update_rate * update_cost) + (call_rate * page_cost)

print('Total Cost:', mobility_cost(0.5, 2, 1.2, 5))

def process_mac_frame(sender, receiver, frame_type, nav_table):
    if frame_type == 'RTS':
        nav_table[receiver] = 'BUSY'
        return 'CTS_SENT'
    elif frame_type == 'CTS':
        nav_table[sender] = 'TRANSMITTING'
        return 'DATA_READY'
    return 'IDLE'

def allocate_slots(requests, total_slots):
    schedule = {}
    current_slot = 0
    for node, req_slots in requests.items():
        if current_slot + req_slots <= total_slots:
            schedule[node] = list(range(current_slot, current_slot + req_slots))
            current_slot += req_slots
        else:
            break
    return schedule

def route_discovery(source, destination, network_graph):
    visited = set()
    queue = [[source]]
    while queue:
        path = queue.pop(0)
        node = path[-1]
        if node == destination:
            return path
        if node not in visited:
            visited.add(node)
            for neighbor in network_graph.get(node, []):
                new_path = list(path)
                new_path.append(neighbor)
                queue.append(new_path)
    return None

