def elect_clusterhead(neighbor_dict):
    # neighbor_dict: {node_id: [list of neighbor ids]}
    ch_map = {}
    for node, nbrs in neighbor_dict.items():
        all_group = nbrs + [node]
        ch = max(all_group)
        ch_map[node] = ch
    return ch_map

def process_multicast_packet(packet, node_id, multicast_groups, forwarding_group):
    if packet['group_id'] not in multicast_groups and node_id not in forwarding_group:
        return "DROP"
    elif node_id in multicast_groups:
        return "DELIVER_TO_APPLICATION"
    else:
        return "FORWARD_PACKET"

def calculate_battery(initial_j, p_active, t_active, p_idle, t_idle, p_sleep, t_sleep):
    total_consumed = (p_active * t_active) + (p_idle * t_idle) + (p_sleep * t_sleep)
    remaining = initial_j - total_consumed
    return max(0.0, (remaining / initial_j) * 100)

# Example usage:
print(f"{calculate_battery(100.0, 0.05, 300, 0.02, 1000, 0.0001, 2300):.2f}%")

def update_trust(current_score, packet_dropped):
    if packet_dropped:
        return max(0.0, current_score - 0.25)
    return min(1.0, current_score + 0.05)

score = 0.8
score = update_trust(score, True) # Drop detected
print(f"Updated Trust Score: {score}")

def evaluate_wifi_security(protocol):
    protocols = {
        "WEP": "High Risk - Broken",
        "WPA2-TKIP": "High Risk - Broken",
        "WPA2-AES": "Moderate - Vulnerable to weak PSK offline attack",
        "WPA3": "Secure - Forward Secrecy & SAE Enabled"
    }
    return protocols.get(protocol.upper(), "Unknown Protocol")

